1	package net.officefloor.hq.app;
2	
3	import java.util.List;
4	import java.util.Map;
5	import java.util.stream.Collectors;
6	import net.officefloor.web.ObjectResponse;
7	
8	/**
9	 * {@code GET /api/projects} — list every project with the NAME of the client it is for (not just the
10	 * id), so the UI can show the join directly. Wired by {@code officefloor/rest/api/projects.GET.yml}.
11	 */
12	public class ProjectsGetLogic {
13	
14	    public void service(ProjectRepository projects, ClientRepository clients,
15	            ObjectResponse<List<ProjectView>> response) {
16	        Map<Long, String> nameByClient = clients.findAll().stream()
17	                .collect(Collectors.toMap(Client::getId, Client::getName));
18	        List<ProjectView> views = projects.findAll().stream()
19	                .map(p -> new ProjectView(p.getId(), p.getName(), p.getClientId(),
20	                        nameByClient.get(p.getClientId())))
21	                .collect(Collectors.toList());
22	        response.send(views);
